      data: { labels: TOPc.map(function (c) { return shortName(c.name); }), datasets: [['cityadd', 'Cities', TC], ['townadd', 'Towns', TW], ['ruraladd', 'Rural areas', TR]].map(function (t) { return { label: t[1], data: TOPc.map(function (c) { return +c[t[0]].toFixed(1); }), backgroundColor: t[2], borderRadius: 2 }; }) },
      options: { indexAxis: 'y', plugins: { legend: { position: 'bottom' }, tooltip: { callbacks: { label: function (c) { return c.dataset.label + ': ' + sg(c.raw, 1) + ' m'; }, afterBody: function (it) { var o = TOPc[it[0].dataIndex]; return 'total ' + sg(o.totadd, 1) + ' m (' + sg(o.grow, 0) + '%) · city share ' + fmt(o.cshare25 * 100, 0) + '% → ' + fmt(o.cshare50 * 100, 0) + '%'; } } } }, scales: { x: Object.assign(axis({ title: 'population change 2025–2050 (millions)' }), { stacked: true }), y: Object.assign(axis({ grid: false }), { stacked: true, ticks: Object.assign({ autoSkip: false }, tick) }) } },
